#!/usr/bin/env python3
"""Map the IAT of a dumped PE image and flag unresolved/corrupted slots."""
import argparse, json, pefile

def main():
    ap = argparse.ArgumentParser(description="IAT mapper for unpacked PE")
    ap.add_argument("--dump", required=True, help="path to dumped binary or rebuilt PE")
    ap.add_argument("--base", default=None)  # optional: observed image base
    args = ap.parse_args()

    pe = pefile.PE(args.dump, fast_load=False)

    entries = []
    if hasattr(pe, 'DIRECTORY_ENTRY_IMPORT'):
        for imp in pe.DIRECTORY_ENTRY_IMPORT:
            dll_name = imp.dll.decode(errors='replace')
            # Use the import name table (not thunk table which may be shifted)
            for func in imp.imports:
                entry = {"dll": dll_name}
                if hasattr(func, 'Name') and func.Name:
                    try:
                        entry["func"] = func.Name.decode(errors='replace')
                        entry["by_name"] = True
                    except UnicodeDecodeError:
                        pass
                elif hasattr(func, 'Ordinal') and not hasattr(func, 'AddressOfData'):
                    # Ordinal import (no name in thunk table)
                    entry["func_or_ord"] = f"ord_{func.Ordinal}"
                    if args.base:
                        func_va = func.AddressOfData + int(args.base, 16)
                        entry["func_va"] = hex(func_va)
                elif hasattr(func, 'AddressOfData'):
                    # Function-pointer import
                    entry["addr_or_ord"] = f"0x{func.AddressOfData:x}"
                    if args.base:
                        func_va = func.AddressOfData + int(args.base, 16)
                        entry["func_va"] = hex(func_va)
                else:
                    # Import thunk with no name (forwarder or resolved from decrypted region)
                    entry["status"] = "unresolved" if not hasattr(func, 'AddressOfData') else "pointer"
                    entry["slot_raw"] = None
                entries.append(entry)

    iat_dir = pe.OPTIONAL_HEADER.DATA_DIRECTORY[pe.DIRECTORY_ENTRY_IMPORT] if hasattr(pe, 'DIRECTORY_ENTRY_IMPORT') else None
    out = {
        "imports": entries,
        "iat_virt": hex(iat_dir.VirtualAddress) if iat_dir and iat_dir.VirtualAddress else None,
        "iat_rva" : hex(pe.OPTIONAL_HEADER.DATA_DIRECTORY[1].VirtualAddress) if hasattr(pe.OPTIONAL_HEADER, 'DATA_DIRECTORY') and pe.OPTIONAL_HEADER.DATA_DIRECTORY[1].VirtualAddress else None,
    }

    print(json.dumps(out, indent=2))

if __name__ == "__main__":
    main()

