#!/usr/bin/env python3
"""Launch the sample under Wine, watch its mapped image, dump on decryption."""
import hashlib, json, os, signal, subprocess, sys, time

OUT           = "/out"
TARGET        = sys.argv[1] if len(sys.argv) > 1 else "/target/sample.exe"

# Derive SizeOfImage from the PE at runtime so this works for any packed sample.
try:
    import pefile as pf
except ImportError:
    print("pefile not installed; using default constants")
    pf = None

if pf is not None:
    try:
        pe = pf.PE(TARGET)
        SIZE_OF_IMAGE = pe.OPTIONAL_HEADER.SizeOfImage
        # Locate the packed section (the one at RVA 0x1000 with largest size)
        PACKED_RVA = None
        PACKED_SZ  = None
        for s in pe.sections:
            if s.VirtualAddress == 0x1000:
                PACKED_RVA = s.VirtualAddress
                PACKED_SZ  = min(s.SizeOfRawData, s.Misc_VirtualSize)
                break
    except Exception as e:
        print(f"Warning: could not parse {TARGET} for constants: {e}")

WATCH_SPAN    = SIZE_OF_IMAGE             # hash full [base, base+SizeOfImage] as change detector
POLL_S        = 0.25
DEADLINE_S    = int(os.environ.get("DEADLINE_S", "120"))
SCHEDULE      = [1.0, 2.0, 3.0, 10.0, 25.0, 45.0]

def parse_maps(pid):
    out = []
    try:
        with open(f"/proc/{pid}/maps") as fh:
            for line in fh:
                rng, perms, _off, _dev, _ino, *rest = line.split()
                start, end = (int(x, 16) for x in rng.split("-"))
                out.append((start, end, perms, rest[0] if rest else ""))
    except (FileNotFoundError, ProcessLookupError, PermissionError):
        pass
    return out

def read_mem(pid, addr, size, chunk=0x10000):
    """Read [addr, addr+size); unreadable pages become zeros. Returns (bytes, holes)."""
    buf, holes = bytearray(), 0
    with open(f"/proc/{pid}/mem", "rb", buffering=0) as mem:
        for off in range(0, size, chunk):
            n = min(chunk, size - off)
            try:
                mem.seek(addr + off)
                data = mem.read(n)
                if data is None or len(data) != n:
                    data = (data or b"").ljust(n, b"\0"); holes += 1
            except (OSError, ValueError):
                data = b"\0" * n; holes += 1
            buf += data
    return bytes(buf), holes

def looks_like_target(pid, start):
    """MZ + PE\\0\\0 + OptionalHeader.SizeOfImage == our SizeOfImage."""
    try:
        head, _ = read_mem(pid, start, 0x400)
    except OSError:
        return False
    if head[:2] != b"MZ":
        return False
    e_lfanew = int.from_bytes(head[0x3C:0x40], "little")
    if not (0x40 <= e_lfanew <= 0x300) or head[e_lfanew:e_lfanew + 4] != b"PE\0\0":
        return False
    opt = e_lfanew + 0x18
    return int.from_bytes(head[opt + 0x38:opt + 0x3C], "little") == SIZE_OF_IMAGE

def find_image(pids):
    for pid in pids:
        for start, end, perms, _path in parse_maps(pid):
            if "r" in perms and (end - start) >= 0x1000 and looks_like_target(pid, start):
                return pid, start
    return None, None

def descendants(root):
    """root + all descendants, via /proc/*/stat PPid walk."""
    kids, seen = {root}, True
    while seen:
        seen = False
        for entry in os.listdir("/proc"):
            if not entry.isdigit() or int(entry) in kids:
                continue
            try:
                with open(f"/proc/{entry}/status") as fh:
                    ppid = next(int(l.split()[1]) for l in fh if l.startswith("PPid:"))
            except (OSError, StopIteration, ValueError):
                continue
            if ppid in kids:
                kids.add(int(entry)); seen = True
    return sorted(kids)

def dump(pid, base, tag, idx, manifest):
    img, holes = read_mem(pid, base, SIZE_OF_IMAGE)
    name = f"dump_{idx:02d}_{tag}.bin"
    with open(os.path.join(OUT, name), "wb") as fh:
        fh.write(img)
    rwx = []
    for start, end, perms, path in parse_maps(pid):
        if "x" in perms and "w" in perms and not path and (end - start) >= 0x10000:
            blob, _ = read_mem(pid, start, end - start)
            rname = f"rwx_{idx:02d}_{start:x}.bin"
            with open(os.path.join(OUT, rname), "wb") as fh:
                fh.write(blob)
            rwx.append({"file": rname, "start": hex(start), "size": end - start})
    with open(os.path.join(OUT, f"dump_{idx:02d}.maps"), "w") as fh:
        for s, e, p, path in parse_maps(pid):
            fh.write(f"{s:016x}-{e:016x} {p} {path}\n")
    manifest.append({"idx": idx, "tag": tag, "pid": pid, "base": hex(base),
                     "file": name, "zero_filled_chunks": holes, "rwx": rwx})
    print(f"[dump] #{idx} {tag} pid={pid} base={base:#x} holes={holes} rwx={len(rwx)}", flush=True)

def main():
    os.makedirs(OUT, exist_ok=True)
    # Ensure /out is writable under root bind-mount (permission mismatch between container/host UID).
    os.system("chmod 777 " + OUT + " >/dev/null 2>&1")
    # Start Xvfb manually with explicit screen size so Wine can create windows.
    xvfb = subprocess.Popen(["Xvfb", ":99", "-screen", "0", "1024x768x24"], close_fds=True)
    env = {"DISPLAY": ":99", **os.environ}
    proc = subprocess.Popen(
        ["strace", "-f", "-o", f"{OUT}/trace.log", "wine64", TARGET],
        stdout=open(f"{OUT}/wine.stdout", "wb"),
        stderr=open(f"{OUT}/wine.stderr", "wb"),
        preexec_fn=os.setsid,
        env=env,
    )
    t0, idx, manifest = time.time(), 0, []
    pid = base = None
    baseline = None
    pending = list(SCHEDULE)

    while time.time() - t0 < DEADLINE_S:
        now = time.time() - t0
        if pid is None:
            pid, base = find_image(descendants(proc.pid))
            if pid is not None:
                print(f"[find] image pid={pid} base={base:#x} @t={now:.1f}s", flush=True)
                blob, _ = read_mem(pid, base, SIZE_OF_IMAGE)  # hash full mapped image
                baseline = hashlib.sha256(blob).hexdigest()
        else:
            if not os.path.exists(f"/proc/{pid}"):
                print(f"[exit] target pid {pid} gone @t={now:.1f}s", flush=True)
                break
            blob, _ = read_mem(pid, base, SIZE_OF_IMAGE)   # compare full image hash
            digest = hashlib.sha256(blob).hexdigest()
            if baseline is not None and digest != baseline:
                idx += 1; dump(pid, base, "decrypt-change", idx, manifest)
                baseline = digest
            while pending and now >= pending[0]:
                pending.pop(0)
                idx += 1; dump(pid, base, f"t{int(now)}s", idx, manifest)
        time.sleep(POLL_S)

    if pid is not None and os.path.exists(f"/proc/{pid}"):
        idx += 1; dump(pid, base, "final", idx, manifest)

    try:
        os.killpg(os.getpgid(proc.pid), signal.SIGKILL)
    except (ProcessLookupError, PermissionError):
        pass
    try:
        xvfb.terminate()
    except ProcessLookupError:
        pass
    with open(os.path.join(OUT, "manifest.json"), "w") as fh:
        json.dump({"image_base": hex(base) if base else None,
                   "size_of_image": hex(SIZE_OF_IMAGE), "dumps": manifest}, fh, indent=2)
    print(f"[done] {len(manifest)} dumps → {OUT}/manifest.json", flush=True)

if __name__ == "__main__":
    sys.exit(main())

